mapper.sql:
WHERE r.receipt_date>=#{from_date} AND r.receipt_date<=#{to_date}
AND r.account_id=#{account_id}
AND r.supplier_id=#{supplier_id}
AND r.purchase_order_id IS NOT NULL
AND r.purchase_order_id IS NULL AND r.status<>'HISTORY'
AND r.purchase_order_id IS NULL AND r.status='HISTORY'
AND i.tax_type=#{tax_type}
AND i.tax_type IS NULL
AND i.amount_source='ORDER_ESTIMATE'
AND i.amount_check_status=#{check_status}
AND i.amount_check_status IN ('PRICE_DIFF','QTY_DIFF')

  AND EXISTS (SELECT 1 FROM tb_supplier_ingredient_product kp WHERE kp.supplier_product_id=i.supplier_product_id
              AND (kp.product_name LIKE CONCAT('%',#{keyword},'%') OR kp.supplier_item_code=#{keyword}))

mapper.select:
SELECT i.goods_receipt_item_id,i.goods_receipt_id,DATE_FORMAT(r.receipt_date,'%Y-%m-%d') receipt_date,r.status receipt_status, source, r.account_id,(SELECT a.account_name FROM the_full.tb_account a WHERE a.account_id=r.account_id LIMIT 1) account_name, s.supplier_id,s.supplier_code,s.supplier_name,ss.external_site_code site_code,ss.external_site_name site_name, r.purchase_order_id,po.client_ord,oi.client_ord_item, p.supplier_item_code,COALESCE(oi.product_name_snapshot,p.product_name) product_name, i.received_qty,i.order_unit,i.unit_price,i.supply_amount,i.vat_amount,i.total_amount, i.tax_type,i.amount_source,i.amount_check_status,DATE_FORMAT(i.amount_checked_at,'%Y-%m-%d %H:%i') amount_checked_at, (SELECT COALESCE(SUM(b.supply_amount),0) FROM tb_supplier_bill_line b WHERE b.purchase_order_item_id=i.purchase_order_item_id AND i.purchase_order_item_id IS NOT NULL) bill_supply_amount, (SELECT COALESCE(SUM(b.billed_qty),0) FROM tb_supplier_bill_line b WHERE b.purchase_order_item_id=i.purchase_order_item_id AND i.purchase_order_item_id IS NOT NULL) bill_qty, i.ingredient_id,COALESCE(ai.ingredient_name_std,ai.ingredient_name_raw) ingredient_name, (SELECT COUNT(*) FROM tb_purchase_tax_invoice_line tl WHERE tl.goods_receipt_item_id=i.goods_receipt_item_id) invoice_linked
LEFT JOIN tb_supplier_ingredient_product p ON p.supplier_product_id=i.supplier_product_id LEFT JOIN tb_supplier_account_site ss ON ss.supplier_account_site_id=r.supplier_account_site_id LEFT JOIN tb_account_purchase_order po ON po.purchase_order_id=r.purchase_order_id LEFT JOIN tb_account_purchase_order_item oi ON oi.purchase_order_item_id=i.purchase_order_item_id LEFT JOIN tb_account_ingredient_master ai ON ai.account_id=r.account_id AND ai.ingredient_id=i.ingredient_id
ORDER BY r.receipt_date DESC,s.supplier_id,r.goods_receipt_id,i.goods_receipt_item_id LIMIT #{limit} OFFSET #{offset}

SELECT DISTINCT b.purchase_order_item_id FROM tb_supplier_bill_line b
 WHERE b.purchase_order_item_id IS NOT NULL AND b.bill_date>=#{from_date} AND b.bill_date<=#{to_date}
 AND b.account_id=#{account_id}

SELECT s.supplier_code,s.supplier_name,DATE_FORMAT(b.bill_date,'%Y-%m-%d') bill_date,b.account_id,b.client_ord,b.client_ord_item,
       b.supplier_item_code,b.billed_qty,b.supply_amount,b.vat_amount,b.total_amount
  FROM tb_supplier_bill_line b JOIN tb_supplier s ON s.supplier_id=b.supplier_id
 WHERE b.purchase_order_item_id IS NULL AND b.bill_date>=#{from_date} AND b.bill_date<=#{to_date}
 AND b.account_id=#{account_id}
 ORDER BY b.bill_date DESC LIMIT 100
